(function(root){
  'use strict';
  // Concrete visual descriptions keep guided choices useful to the image model.
  const words={
    photos:{
      look:{'Contemporary digital':'clean contemporary digital photography, natural color and precise detail','35mm color film':'35mm color-film photograph with visible fine grain and gentle tonal rolloff','Black & white':'black-and-white photograph with a full range of tones','Editorial':'editorial photograph with deliberate styling and a clear focal point','Instant film':'instant-film photograph with soft contrast and characteristic print color','Medium format':'medium-format photograph with rich tonal detail','Lifestyle':'candid lifestyle photograph with natural interaction','Documentary':'observational documentary photograph with believable details','Fashion':'fashion photograph with intentional clothing, pose and styling','Fine art':'fine-art photograph with deliberate composition and restrained detail','Cinematic still':'cinematic photographic still with a clear scene and atmospheric depth','Macro':'macro photograph with close detail and shallow depth of field','Long exposure':'long-exposure photograph with visible motion over time','High key':'high-key photograph with light tones and soft shadows','Low key':'low-key photograph with deep shadows and a controlled focal light'},
      process:{'Silver gelatin':'silver gelatin monochrome print, tactile grain and deep blacks','1970s color':'1970s color-film palette with warm muted tones','1990s editorial':'1990s magazine color treatment with subtle grain','Kodachrome':'Kodachrome-inspired slide color with rich reds and warm contrast','Ektachrome':'Ektachrome-inspired slide color with crisp cool tones','Portra-inspired':'Portra-inspired color negative with soft skin tones','Tri-X-inspired':'Tri-X-inspired black-and-white grain and contrast','Polaroid-style':'Polaroid-style instant print with soft color and print borders','Slide film':'color slide-film look with distinct saturated colors','Color negative':'color-negative film look with soft highlights and fine grain','Cross processed':'cross-processed film colors with deliberate color shifts','Cyanotype':'cyanotype print with deep Prussian blue and pale highlights','Wet plate':'wet-plate photographic texture with antique tonal range','Contemporary':'present-day photographic processing with natural color'},
      light:{'Window light':'Soft daylight enters from a window on one side, with gentle shadow falloff.','Golden hour':'Warm low sunlight enters from the side and leaves long soft shadows.','Overcast':'Broad overcast daylight gives even light and soft shadows.','Studio softbox':'A large studio softbox creates controlled soft highlights and shadows.','Hard sunlight':'Direct sun creates crisp shadows and bright highlights.','Candlelight':'Warm candlelight is the visible light source, with nearby falloff.','Warm practical light':'Visible lamps within the scene cast warm pools of light and natural shadows.','Rembrandt light':'A single portrait key light above and to one side leaves a small triangle of light beneath the far eye.','Butterfly light':'A frontal raised beauty light leaves a small symmetrical shadow beneath the nose.','Loop light':'A raised side light leaves a small loop-shaped cheek shadow.','Split light':'A side key light illuminates one half of the face and leaves the other in shadow.','Rim light':'A back-side light defines the subject edge while the front remains controlled.','Backlit':'The main light sits behind the subject, defining the silhouette and edge.','Top light':'Light falls from above, creating downward shadows.','Clamshell light':'Soft portrait light from above and a gentle fill below shapes the face.','Direct flash':'Direct camera flash creates crisp foreground light and quick shadow falloff.','Blue hour':'Cool twilight gives soft ambient light and muted shadows.'},
      framing:{'Close-up':'The subject fills most of the frame.','Waist-up':'The person is framed from the waist upward.','Wide scene':'A wide view shows the subject within its surroundings.','Top-down':'The camera looks straight down from overhead.','Low angle':'The camera looks upward from a low position.','Symmetrical':'The composition is balanced around a central axis.','Environmental portrait':'The person appears within a setting that explains their context.','Extreme close-up':'One small detail fills the frame.','Eye level':'The camera sits at the subject’s eye level.','Negative space':'Clear open space surrounds the main subject.','Rule of thirds':'The main subject sits near a third-line intersection.','Dutch angle':'The frame is deliberately tilted.','Through foreground':'A near foreground element frames the subject.','Panorama':'The scene stretches across a wide horizontal frame.'}
    },
    art:{medium:{Watercolor:'watercolor on textured paper with visible washes','Oil painting':'oil painting with layered pigment and visible brush texture','Ink drawing':'ink drawing with deliberate line weight','Colored pencil':'colored-pencil illustration with layered strokes','Cut paper':'cut-paper artwork with distinct overlapping shapes','Digital illustration':'digital illustration with crafted forms and clear edges',Gouache:'gouache painting with opaque matte color',Charcoal:'charcoal drawing with smudged dark gestures',Pastel:'pastel artwork with powdery blended color',Linocut:'linocut print with carved marks',Woodcut:'woodcut print with bold carved marks',Etching:'etched print with fine engraved lines',Acrylic:'acrylic painting with opaque strokes','Pixel art':'pixel artwork with deliberate block-shaped details'}},
    graphics:{language:{'Flat shapes':'flat color shapes with crisp boundaries','Paper cut':'layered cut paper with visible edges and subtle paper shadows','Line art':'expressive line drawing with clear contours','Soft 3D':'softly rounded three-dimensional forms','Screen print':'screen-printed ink layers and slight registration texture','Hand drawn':'hand-drawn contours with small natural irregularities',Geometric:'simple precise geometric shapes',Organic:'flowing organic shapes',Duotone:'two-tone color treatment',Halftone:'printed halftone dot texture','Clay-like':'soft sculpted clay forms',Collage:'layered collage of distinct materials'}},
    transparent:{edge:{'Clean cutout':'a precise isolated silhouette','Soft natural edge':'fine natural hair, fur or translucent edges','Illustrated edge':'a deliberately drawn outline','Paper texture':'visible paper fibers at the edges','Shadow included':'a soft attached contact shadow','No shadow':'no ground or cast shadow','Die-cut border':'a clean white die-cut sticker border','Feathered edge':'a gently feathered edge','Crisp vector-like':'a sharply simplified contour','Hand-torn edge':'irregular torn-paper edges'}}
  };
  const medium={photos:'photograph',art:'artwork',graphics:'graphic',posters:'design',transparent:'isolated asset',references:'composed image',storyboards:'image',comics:'illustration'};
  const primary={photos:'type',graphics:'asset',posters:'purpose',transparent:'asset',storyboards:'form',comics:'format'};
  function build(catalog,mode,d){
    const idea=String(d.idea||'').trim(),choices=d.choices||{},parts=[];
    if(mode==='freeform')return idea.trim();
    const first=primary[mode],label=first&&choices[first]?.toLowerCase();
    const kind=label?`${label}${label.endsWith(medium[mode])?'':` ${medium[mode]||'image'}`}`:(medium[mode]||'image');
    const opening=`${/^[aeiou]/i.test(kind)?'An':'A'} ${kind}${idea?` showing ${idea.replace(/[.!?]+$/,'')}`:''}`;
    parts.push(opening+'.');
    for(const section of catalog[mode]?.sections||[]){
      const selected=choices[section.id];if(!selected)continue;
      if(section.id===first)continue;
      const description=section.options.find(([title])=>title===selected)?.[1]||'';
      const phrase=words[mode]?.[section.id]?.[selected];
      if(phrase){parts.push(phrase.endsWith('.')?phrase:phrase+'.');continue;}
      const category=section.title.toLowerCase();
      parts.push(`${category}: ${selected}${description?` (${description.toLowerCase()})`:''}.`);
    }
    if(d.exact?.trim())parts.push(`The visible text reads "${d.exact.trim()}" exactly.`);
    return parts.join(' ');
  }
  const api={build,words};
  if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.promptLanguage=api;
})(typeof window!=='undefined'?window:globalThis);
